import {clone} from '../document/model.js';import {convertToPath} from './shapes.js';
export const lineStyles=['solid','dashed','dotted'];export const lineProfiles=['uniform','taper-both','taper-start','taper-end','brush'];
export function profileWidth(profile,t){return profile==='taper-both'?Math.sin(Math.PI*t):profile==='taper-start'?t:profile==='taper-end'?1-t:profile==='brush'?.25+.75*Math.sin(Math.PI*t)**.6:1;}
export function sampledPaths(n){const v=clone(n);convertToPath(v);const paths=[];let pts=[],first,prev;const segment=(a,b)=>{const c=a.out||a,d=b.in||b,steps=a.out||b.in?24:Math.max(2,Math.ceil(Math.hypot(b.x-a.x,b.y-a.y)/8));for(let i=1;i<=Math.min(100,steps);i++){const t=i/Math.min(100,steps),s=1-t;pts.push({x:s**3*a.x+3*s*s*t*c.x+3*s*t*t*d.x+t**3*b.x,y:s**3*a.y+3*s*s*t*c.y+3*s*t*t*d.y+t**3*b.y});}};const finish=closed=>{if(pts.length>1)paths.push({points:pts,closed});pts=[];prev=null;};for(const p of v.nodes){if(!prev||p.move){if(pts.length)finish(false);pts=[{x:p.x,y:p.y}];first=p;}else segment(prev,p);prev=p;if(p.close){segment(p,first);finish(true);}}if(prev){if(v.closed)segment(prev,first);finish(v.closed);}return paths;}
export function strokeOutline(n){const outlines=[];for(const {points:p} of sampledPaths(n)){const distances=[0];for(let i=1;i<p.length;i++)distances.push(distances[i-1]+Math.hypot(p[i].x-p[i-1].x,p[i].y-p[i-1].y));const length=distances.at(-1);if(!length)continue;const left=[],right=[];for(let i=0;i<p.length;i++){const a=p[Math.max(0,i-1)],b=p[Math.min(p.length-1,i+1)],dx=b.x-a.x,dy=b.y-a.y,l=Math.hypot(dx,dy)||1,w=n.strokeWidth/2*profileWidth(n.strokeProfile,distances[i]/length);left.push({x:p[i].x-dy/l*w,y:p[i].y+dx/l*w});right.push({x:p[i].x+dy/l*w,y:p[i].y-dx/l*w});}const all=[...left,...right.reverse()];outlines.push('M '+all.map(p=>`${p.x} ${p.y}`).join(' L ')+' Z');}return outlines.join(' ');}
